## Source &mdash; `tests/core/test_user_bench.cpp`

```cpp
/**************************************************************************/
/*  test_user_bench.cpp                                                   */
/**************************************************************************/

#include "tests/test_macros.h"

TEST_FORCE_LINK(test_user_bench)

#include "core/variant/container_type_validate.h"
#include "core/variant/dictionary.h"
#include "core/variant/variant.h"

#include <algorithm>
#include <chrono>

namespace TestUserBench {

static uint64_t sink = 0;

static ContainerType ct(Variant::Type p_type) {
	ContainerType t;
	t.variant_type = p_type;
	return t;
}

// Source builders. Each returns a dictionary of `p_n` entries.

static Dictionary src_untyped_int(int p_n) {
	Dictionary d;
	for (int i = 0; i < p_n; i++) {
		d[i] = i;
	}
	return d;
}

static Dictionary src_untyped_float(int p_n) {
	Dictionary d;
	for (int i = 0; i < p_n; i++) {
		d[double(i)] = double(i);
	}
	return d;
}

static Dictionary src_untyped_string(int p_n) {
	Dictionary d;
	for (int i = 0; i < p_n; i++) {
		d[itos(i)] = itos(i) + "_value";
	}
	return d;
}

static Dictionary src_typed_int(int p_n) {
	Dictionary d;
	d.set_typed(ct(Variant::INT), ct(Variant::INT));
	for (int i = 0; i < p_n; i++) {
		d[i] = i;
	}
	return d;
}

static Dictionary src_typed_string_int(int p_n) {
	Dictionary d;
	d.set_typed(ct(Variant::STRING), ct(Variant::INT));
	for (int i = 0; i < p_n; i++) {
		d[itos(i)] = i;
	}
	return d;
}

// Times `p_reps` calls of `target.assign(p_source)` where target is freshly
// typed <p_key, p_value> each rep. Returns the median in microseconds.
static double bench_assign(const Dictionary &p_source, Variant::Type p_key, Variant::Type p_value, int p_reps) {
	LocalVector<double> samples;
	for (int r = 0; r < p_reps; r++) {
		Dictionary target;
		target.set_typed(ct(p_key), ct(p_value));

		const auto begin = std::chrono::steady_clock::now();
		target.assign(p_source);
		const auto end = std::chrono::steady_clock::now();

		samples.push_back(std::chrono::duration<double, std::micro>(end - begin).count());
		sink += target.size();
	}
	std::sort(samples.ptr(), samples.ptr() + samples.size());
	return samples[samples.size() / 2];
}

static int user_bench() {
	const int sizes[] = { 1000, 10000, 100000 };

	print_line("scenario,n,median_us");

	for (int s = 0; s < 3; s++) {
		const int n = sizes[s];
		const int reps = MAX(5, 2000000 / n);

		// A: fast path, no conversion on either side (control).
		{
			const Dictionary src = src_typed_string_int(n);
			print_line(vformat("A_fastpath_same_type,%d,%f", n, bench_assign(src, Variant::STRING, Variant::INT, reps)));
		}
		// B: untyped source, elements already the target type.
		{
			const Dictionary src = src_untyped_int(n);
			print_line(vformat("B_untyped_no_convert,%d,%f", n, bench_assign(src, Variant::INT, Variant::INT, reps)));
		}
		// C: untyped source, every key and value converts (float -> int).
		{
			const Dictionary src = src_untyped_float(n);
			print_line(vformat("C_untyped_convert_both,%d,%f", n, bench_assign(src, Variant::INT, Variant::INT, reps)));
		}
		// D: typed source, key converts only (int -> float).
		{
			const Dictionary src = src_typed_int(n);
			print_line(vformat("D_typed_convert_key,%d,%f", n, bench_assign(src, Variant::FLOAT, Variant::INT, reps)));
		}
		// E: heap-backed keys and values.
		{
			const Dictionary src = src_untyped_string(n);
			print_line(vformat("E_untyped_string,%d,%f", n, bench_assign(src, Variant::STRING, Variant::STRING, reps)));
		}
	}

	print_line(vformat("sink,%d,0", sink));
	return 0;
}

REGISTER_TEST_COMMAND("user-bench", &user_bench)

} // namespace TestUserBench
```

